const originalText = new WeakMap()
const originalAttributes = new WeakMap()
const arabicDigits = new Intl.NumberFormat('ar-BH', { useGrouping: false })

function translateText(value) {
  const leading = value.match(/^\s*/)?.[0] ?? ''
  const trailing = value.match(/\s*$/)?.[0] ?? ''
  const text = value.trim()
  if (!text) return value
  const normalizedText = text.replace(/\s+/g, ' ')

  let translated = ARABIC_TEXT[normalizedText] ?? ARABIC_CASE_INSENSITIVE[normalizedText.toLocaleLowerCase('en')] ?? text
  Object.entries(PHRASES).sort(([left], [right]) => right.length - left.length).forEach(([english, arabic]) => {
    translated = translated.replaceAll(english, arabic)
  })
  Object.entries(TERMS).sort(([left], [right]) => right.length - left.length).forEach(([english, arabic]) => {
    const escaped = english.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')
    translated = translated.replace(
      new RegExp(`(^|[^\\p{L}\\p{N}])${escaped}(?=$|[^\\p{L}\\p{N}])`, 'gu'),
      (_, prefix) => `${prefix}${arabic}`,
    )
  })
  translated = translated
    .replace(/(\d+) systems?$/i, '$1 نظام')
    .replace(/(\d+) groups?/i, '$1 مجموعة')
    .replace(/(\d+) entries?/i, '$1 مدخل')
    .replace(/(\d+) properties?/i, '$1 خاصية')
  translated = translated.replace(/\b(\d+)\b/g, (number) => arabicDigits.format(Number(number)))
  return `${leading}${translated}${trailing}`
}

export function localizeDocument(root, language) {
  const isArabic = language === 'ar'
  document.title = isArabic ? 'أطلس التسلسل الزمني العالمي' : 'Universal Chronology Atlas'

  const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT)
  let node = walker.nextNode()
  while (node) {
    const parent = node.parentElement
    if (parent && !['SCRIPT', 'STYLE'].includes(parent.tagName)) {
      if (!originalText.has(node)) originalText.set(node, node.nodeValue)
      const source = originalText.get(node)
      const preserveEnglishFictionText = parent.closest?.('.fiction-value')
      node.nodeValue = isArabic && !preserveEnglishFictionText ? translateText(source) : source
    }
    node = walker.nextNode()
  }

  root.querySelectorAll?.('[aria-label], [title], [placeholder], [data-label]').forEach((element) => {
    if (!originalAttributes.has(element)) {
      originalAttributes.set(element, {
        ariaLabel: element.getAttribute('aria-label'),
        title: element.getAttribute('title'),
        placeholder: element.getAttribute('placeholder'),
        dataLabel: element.getAttribute('data-label'),
      })
    }
    const source = originalAttributes.get(element)
    for (const [attribute, key] of [['aria-label', 'ariaLabel'], ['title', 'title'], ['placeholder', 'placeholder'], ['data-label', 'dataLabel']]) {
      if (source[key] !== null) element.setAttribute(attribute, isArabic ? translateText(source[key]) : source[key])
    }
  })
}
